Here's a comprehensive rewrite with all security measures:

```javascript
// Secure application implementation
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const { validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();

// 1. Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// 4. Body Parsing with Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. XSS Protection
app.use(xss());

// 6. Security Logger
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/security.log',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    })
  ]
});

// 7. Authentication Middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    securityLogger.warn('Unauthorized access attempt', { 
      ip: req.ip, 
      path: req.path 
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const user = jwt.verify(token, process.env.JWT_SECRET);
    req.user = user;
    securityLogger.info('Authenticated request', { 
      userId: user.id, 
      path: req.path 
    });
    next();
  } catch (err) {
    securityLogger.warn('Invalid token attempt', { 
      ip: req.ip, 
      path: req.path 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// 8. Routes
app.get('/health', (req, res) => {
  securityLogger.info('Health check', { ip: req.ip });
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

app.get('/users', authenticateToken, (req, res, next) => {
  try {
    // Check authorization
    if (!req.user.isAdmin) {
      securityLogger.warn('Unauthorized user data access', { 
        userId: req.user.id 
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    // Return sanitized data
    const users = [
      { id: 1, name: 'Alice' }, // Email removed for privacy
      { id: 2, name: 'Bob' }
    ];

    res.json(users);
  } catch (err) {
    next(err);
  }
});

// 9. Error Handling
app.use((err, req, res, next) => {
  securityLogger.error('Application error', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    ip: req.ip
  });

  const isProduction = process.env.NODE_ENV === 'production';
  res.status(err.status || 500).json({
    error: isProduction ? 'Internal server error' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// 10. 404 Handler
app.use((req, res) => {
  securityLogger.warn('404 Not Found', { 
    ip: req.ip,
    url: req.url,
    method: req.method
  });
  res.status(404).json({ error: 'Not found' });
});

module.exports = app;
```

